struct Instrumented: ViewModifier {                // the enhancer as a type
    let name: String
    func body(content: Content) -> some View {      // wrapped view arrives as content
        content.onAppear { Analytics.track(name) }
    }
}

extension View {
    func instrumented(_ n: String) -> some View { modifier(Instrumented(name: n)) }
}
PricePanel().instrumented("price_panel")            // applied where it is used
